package com.lexiscan.report; import com.lexiscan.analysis.*; import com.lexiscan.document.Document; import com.lowagie.text.FontFactory; import com.lowagie.text.Paragraph; import com.lowagie.text.pdf.PdfWriter; import org.springframework.stereotype.Service; import java.io.*; import java.util.List;
@Service public class ReportService { public byte[] generate(Document d,AnalysisResult r,List<Clause> clauses)throws Exception{var out=new ByteArrayOutputStream();var pdf=new com.lowagie.text.Document();PdfWriter.getInstance(pdf,out);pdf.open();pdf.add(new Paragraph("LexiScan Legal Document Analysis",FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));pdf.add(new Paragraph("Document: "+d.getFileName()));pdf.add(new Paragraph("Overall risk: "+r.getOverallRiskScore()+"/100 ("+r.getOverallRiskLevel()+")"));pdf.add(new Paragraph("\n"+r.getSummary()));pdf.add(new Paragraph("\nFlagged clauses",FontFactory.getFont(FontFactory.HELVETICA_BOLD,14)));for(var c:clauses)if(!"LOW".equals(c.getRiskLevel()))pdf.add(new Paragraph(c.getCategory()+" — "+c.getRiskLevel()+": "+c.getRiskReason()+"\n"+c.getClauseText().substring(0,Math.min(350,c.getClauseText().length()))+"\n"));pdf.add(new Paragraph("\nThis tool assists understanding and is not legal advice.",FontFactory.getFont(FontFactory.HELVETICA_OBLIQUE,9)));pdf.close();return out.toByteArray();} }
